   253  /**
   254   * hb_subset:
   255   * @source: font face data to be subset.
   256   * @input: input to use for the subsetting.
   257   *
   258   * Subsets a font according to provided input.
   259   **/
   260  hb_face_t *
   261  hb_subset (hb_face_t *source,
   262             hb_subset_input_t *input)
   263  {
   264    if (unlikely (!input || !source)) return hb_face_get_empty ();
   265
   266    hb_subset_plan_t *plan = hb_subset_plan_create (source, input);
   267
   268    hb_tag_t table_tags[32];
   269    unsigned int offset = 0, count;
   270    bool success = true;
   271    do {
   272      count = ARRAY_LENGTH (table_tags);
   273      hb_face_get_table_tags (source, offset, &count, table_tags);
   274      for (unsigned int i = 0; i < count; i++)
   275      {
   276        hb_tag_t tag = table_tags[i];
   277        if (_should_drop_table (plan, tag))
   278        {
   279          DEBUG_MSG(SUBSET, nullptr, "drop %c%c%c%c", HB_UNTAG (tag));
   280          continue;
   281        }
   282        success = success && _subset_table (plan, tag);
   283      }
   284      offset += count;
   285    } while (success && count == ARRAY_LENGTH (table_tags));
   286
   287    hb_face_t *result = success ? hb_face_reference (plan->dest) : hb_face_get_empty ();
   288    hb_subset_plan_destroy (plan);
   289    return result;
   290  }
